briefing.source:
// Compact "what needs attention" read. Read-only.
// Run with --strict=false: otherwise a GraphQL error throws and the envelope is lost.
// gqlcli script --file .agents/skills/factorio-gameplay/scripts/briefing.js \
//   --arg '{"watch":[{"item":"iron-plate","minimum":100}],"area":{"leftTopX":-128,"leftTopY":-128,"rightBottomX":128,"rightBottomY":128}}'
// Input (all optional): surface, force, window (ONE_MINUTE|TEN_MINUTES|ONE_HOUR),
//   area (<=1024 tiles/side; omit = whole surface), watch [{item,minimum}], limit.
async function run(gql, input) {
  input = input || {}
  const vars = {
    input: {
      surface: input.surface || "nauvis",
      force: input.force || "player",
      window: input.window || "ONE_MINUTE",
      attentionLimit: input.limit || 20,
      watchItems: input.watch || [],
    },
  }
  if (input.area) vars.input.area = input.area
  const r = await gql.query(
    `query($input: FactoryBriefingInput!) {
      status { tick speed paused players { name } }
      factoryBriefing(input: $input) {
        attentionTotal
        attentionCounts { kind count }
        attention { kind severity entity unitNumber position { x y } count message }
        machines { type total working noFuel noPower noIngredients outputFull idle other }
        power { productionWatts consumptionWatts networks }
        research { enabled currentTechnology progress queue }
        construction { ghosts ghostsBuildable deconstructionOrders upgradeOrders }
        production { item producedPerMinute consumedPerMinute }
        stockouts { item have minimum shortfall actorHas }
        warnings
      }
    }`,
    vars
  )
  if (r.errors) return { errors: r.errors }
  const b = r.data.factoryBriefing
  return {
    tick: r.data.status.tick,
    paused: r.data.status.paused,
    speed: r.data.status.speed,
    attentionTotal: b.attentionTotal,
    attentionCounts: b.attentionCounts,
    attention: b.attention,
    machines: b.machines,
    power: b.power,
    research: b.research,
    construction: b.construction,
    production: b.production.filter((p) => p.producedPerMinute || p.consumedPerMinute),
    stockouts: b.stockouts,
    warnings: b.warnings,
  }
}

inserter-audit.source:
// Verify every inserter in an area has a real pickup AND drop target. Read-only.
// Run with --strict=false: otherwise a GraphQL error throws and the envelope is lost.
// gqlcli script --file .agents/skills/factorio-gameplay/scripts/inserter-audit.js \
//   --arg '{"area":{"leftTopX":-120,"leftTopY":-45,"rightBottomX":-90,"rightBottomY":-34}}'
// Input: area (<=1024 tiles/side), surface, force. Uses factoryGraph, which returns each inserter with
// its actual pickup/drop endpoint (machines, belts, chests). Returns only suspicious inserters.
// Flags: NO_PICKUP / NO_DROP (empty tile or unsupported entity), SAME_ENDPOINT, and non-working status.
async function run(gql, input) {
  const r = await gql.query(
    `query($area: FactoryAreaInput!, $force: String!, $surface: String!) {
      factoryGraph(area: $area, force: $force, surface: $surface) {
        tick
        inserters {
          inserter { name unitNumber position { x y } direction status pickupPosition { x y } dropPosition { x y } }
          pickup { name type unitNumber position { x y } }
          drop { name type unitNumber position { x y } }
        }
      }
    }`,
    { area: input.area, force: input.force || "player", surface: input.surface || "nauvis" }
  )
  if (r.errors) return { errors: r.errors }
  const g = r.data.factoryGraph
  const issues = []
  for (const c of g.inserters) {
    const flags = []
    if (!c.pickup) flags.push("NO_PICKUP")
    if (!c.drop) flags.push("NO_DROP")
    if (c.pickup && c.drop && c.pickup.unitNumber && c.pickup.unitNumber === c.drop.unitNumber) flags.push("SAME_ENDPOINT")
    const st = c.inserter.status
    if (st && st !== "working" && st !== "normal" && st !== "waiting_for_source_items" && st !== "waiting_for_space_in_destination") flags.push("STATUS_" + st)
    if (flags.length) issues.push({ unitNumber: c.inserter.unitNumber, name: c.inserter.name, position: c.inserter.position,
      direction: c.inserter.direction, pickupPosition: c.inserter.pickupPosition, dropPosition: c.inserter.dropPosition,
      pickup: c.pickup && `${c.pickup.name}@${c.pickup.position.x},${c.pickup.position.y}`,
      drop: c.drop && `${c.drop.name}@${c.drop.position.x},${c.drop.position.y}`, flags })
  }
  return { tick: g.tick, inserters: g.inserters.length, suspicious: issues.length, issues }
}

measure-rate.source:
// Measure real item rates as stock deltas between two game ticks. Read-only.
// Run with --strict=false: otherwise a GraphQL error throws and the envelope is lost.
// gqlcli script --file .agents/skills/factorio-gameplay/scripts/measure-rate.js \
//   --arg '{"items":["iron-plate","copper-plate"],"ticks":1800,"area":{"leftTopX":-8,"leftTopY":-40,"rightBottomX":8,"rightBottomY":-30}}'
// Input: items [names] (required), ticks (default 1800 = 30 s game time; waits wall-clock
//   ticks/60/speed seconds capped by the wait's 10 s wall-clock limit, so keep <= 600 at speed 1
//   or raise the speed), area (stock scope; omit = whole surface),
//   surface, force.
// Rate = delta stock / delta ticks * 3600 per minute. Stock is net of consumption: a consumed item
// shows lower rate than produced. Use production() for produced-vs-consumed in the same window.
async function readStock(gql, input) {
  const stockInput = {
    surface: input.surface || "nauvis", force: input.force || "player",
    itemsLimit: 500, itemsOffset: 0, limit: 1, offset: 0, totalsLimit: 1, totalsOffset: 0,
  }
  if (input.area) stockInput.area = input.area
  const r = await gql.query(
    `query($input: StockInput) { status { tick } stock(input: $input) { tick items { item quality count } } }`,
    { input: stockInput }
  )
  if (r.errors) throw new Error(r.errors[0].message)
  const byItem = {}
  for (const it of r.data.stock.items) byItem[it.item] = (byItem[it.item] || 0) + it.count
  return { tick: r.data.stock.tick, byItem }
}

async function run(gql, input) {
  const items = input.items || []
  const ticks = input.ticks || 1800
  const a = await readStock(gql, input)
  const w = await gql.mutation(
    `mutation($in: WaitUntilInput!) { waitUntil(input: $in) { satisfied timedOut tick } }`,
    { in: { timeoutSeconds: 10, pollSeconds: 0.5, condition: { ticks } } }
  )
  if (w.errors) return { errors: w.errors }
  const b = await readStock(gql, input)
  const dt = b.tick - a.tick
  const rates = {}
  for (const item of items) {
    const d = (b.byItem[item] || 0) - (a.byItem[item] || 0)
    rates[item] = { before: a.byItem[item] || 0, after: b.byItem[item] || 0, delta: d,
                    perMinute: dt > 0 ? +(d / dt * 3600).toFixed(2) : null }
  }
  return { fromTick: a.tick, toTick: b.tick, ticks: dt, timedOut: w.data.waitUntil.timedOut, rates }
}

place-row.source:
// Probe, then place a straight row/column/grid of one item. DRY RUN unless apply:true.
// ALWAYS run with --strict=false: a throw hides the placeMany envelope, and a lost response is not proof of rollback.
// gqlcli script --file .agents/skills/factorio-gameplay/scripts/place-row.js \
//   --arg '{"actor":{"character":"70"},"item":"transport-belt","start":{"x":10.5,"y":4.5},"step":{"x":1,"y":0},"count":12,"direction":4}'
// Input: actor {player|character}, item, start {x,y} (entity CENTER), step {x,y} per entity,
//   count (<=1000), direction (0..15, default 0), apply (default false), surface, force,
//   underground: "INPUT"|"OUTPUT" (optional, for underground belts), message.
// Behaviour: probePlacement on the covered box for the item; with any blocked tile the script returns
//   the blockers and places nothing. Then (apply:true) checks stock and calls placeMany once.
// Footprint note: probePlacement samples tile CENTERS for a 1x1 shape; for machines larger than 1x1 use
//   nearestPlacement or probePlacement with mode SITES instead of this script.
async function run(gql, input) {
  const surface = input.surface || "nauvis"
  const force = input.force || "player"
  const dir = input.direction || 0
  const pts = []
  for (let i = 0; i < input.count; i++) {
    pts.push({ x: input.start.x + i * input.step.x, y: input.start.y + i * input.step.y })
  }
  const xs = pts.map((p) => p.x), ys = pts.map((p) => p.y)
  const area = {
    leftTopX: Math.floor(Math.min(...xs)), leftTopY: Math.floor(Math.min(...ys)),
    rightBottomX: Math.ceil(Math.max(...xs)) + 0.01, rightBottomY: Math.ceil(Math.max(...ys)) + 0.01,
  }
  const probe = await gql.query(
    `query($input: PlacementProbeInput!) {
      probePlacement(input: $input) { tick sampled placeable blocked
        blockedTiles { position { x y } blockers terrain tile } }
    }`,
    { input: { surface, force, prototype: input.item, direction: dir, area,
               mode: "BLOCKED_TILES", siteWidth: 1, siteHeight: 1, maxSites: 1 } }
  )
  if (probe.errors) return { stage: "probe", errors: probe.errors }
  const p = probe.data.probePlacement
  const blockedSet = new Set(p.blockedTiles.map((t) => `${t.position.x},${t.position.y}`))
  const hits = pts.filter((q) => blockedSet.has(`${q.x},${q.y}`))
  const result = { stage: "probe", tick: p.tick, planned: pts.length, blockedOnRoute: hits.length,
                   blocked: p.blockedTiles.filter((t) => hits.some((h) => h.x === t.position.x && h.y === t.position.y)) }
  if (hits.length) return { ...result, placed: 0, note: "route blocked; nothing placed" }
  if (!input.apply) return { ...result, placed: 0, note: "dry run; pass apply:true to place" }

  const placements = pts.map((q) => {
    const e = { position: { x: q.x, y: q.y }, direction: dir }
    if (input.underground) e.undergroundType = input.underground
    return e
  })
  const m = await gql.mutation(
    `mutation($input: PlaceManyInput!) {
      placeMany(input: $input) { placed failed errors { index code message target { position { x y } } }
        entities { name unitNumber position { x y } } }
    }`,
    { input: { actor: input.actor, surface, item: input.item, placements, message: input.message || null } }
  )
  if (m.errors) return { ...result, stage: "place", errors: m.errors, note: "outcome uncertain: inspect before retry" }
  return { ...result, stage: "place", ...m.data.placeMany }
}

survey.source:
// Resource patch survey with distances from a point. Read-only.
// Run with --strict=false: otherwise a GraphQL error throws and the envelope is lost.
// gqlcli script --file .agents/skills/factorio-gameplay/scripts/survey.js \
//   --arg '{"center":{"x":0,"y":0},"radius":128}'
// Input: center {x,y} (default 0,0), radius (default 128, max 128 -> 256 tile box),
//   resources [names] (default iron-ore, copper-ore, coal, stone, uranium-ore, crude-oil),
//   surface, force.
async function run(gql, input) {
  input = input || {}
  const c = input.center || { x: 0, y: 0 }
  const r = Math.min(input.radius || 128, 128)
  const names = input.resources || ["iron-ore", "copper-ore", "coal", "stone", "uranium-ore", "crude-oil"]
  const area = {
    leftTopX: c.x - r, leftTopY: c.y - r, rightBottomX: c.x + r, rightBottomY: c.y + r,
  }
  const out = []
  for (const name of names) {
    const res = await gql.query(
      `query($input: WorldResourcesInput!) {
        worldResources(input: $input) {
          tick pageInfo { total }
          patches { name totalAmount tiles centroid { x y }
            bounds { leftTopX leftTopY rightBottomX rightBottomY }
            nearbyDrills { unitNumber } }
        }
      }`,
      { input: { surface: input.surface || "nauvis", force: input.force || "player", area,
                 groupPatches: true, resourceName: name, drillRadius: 2, limit: 50, offset: 0 } }
    )
    if (res.errors) { out.push({ name, error: res.errors[0].message }); continue }
    for (const p of res.data.worldResources.patches) {
      const dx = p.centroid.x - c.x, dy = p.centroid.y - c.y
      out.push({
        name: p.name, totalAmount: p.totalAmount, tiles: p.tiles,
        centroid: p.centroid, bounds: p.bounds,
        distance: Math.round(Math.sqrt(dx * dx + dy * dy)),
        drills: p.nearbyDrills.length,
      })
    }
  }
  out.sort((a, b) => (a.distance || 1e9) - (b.distance || 1e9))
  return out
}

tech-path.source:
// Unresearched prerequisite closure of a technology, in a valid research order, with pack totals. Read-only.
// Run with --strict=false: otherwise a GraphQL error throws and the envelope is lost.
// gqlcli script --strict=false --file .agents/skills/factorio-gameplay/scripts/tech-path.js --arg '{"technology":"rocket-silo"}'
// Input: technology (required), force (default player), labs (optional, estimates wall time at speed 1,
//   ignoring lab-speed bonuses), unresearchedOnly (default true).
// Output: order[] (name, units, unitSeconds, packs, trigger?, available), totals{units,labSeconds,packs},
//   triggerTechs[] (must be satisfied by an action such as crafting/mining/building, not lab research).
async function run(gql, input) {
  const force = input.force || "player"
  const all = {}
  for (let off = 0; ; off += 100) {
    const r = await gql.query(
      `query($f:String!,$o:Int!){ researchInsights(input:{force:$f,status:ALL,limit:100,offset:$o}){
        pageInfo{ hasMore }
        technologies{ name available researched enabled researchUnitCount researchUnitEnergy researchTriggerJSON
          prerequisites{ name researched } scienceIngredients{ name amount } } } }`,
      { f: force, o: off }
    )
    if (r.errors) return { errors: r.errors }
    for (const t of r.data.researchInsights.technologies) all[t.name] = t
    if (!r.data.researchInsights.pageInfo.hasMore) break
  }
  const target = all[input.technology]
  if (!target) return { error: "unknown technology " + input.technology }
  const seen = new Set(), order = []
  const visit = (name) => {
    if (seen.has(name)) return
    seen.add(name)
    const t = all[name]
    if (!t) return
    for (const p of t.prerequisites) if (!p.researched) visit(p.name)
    if (!t.researched) order.push(t)
  }
  visit(input.technology)
  const totals = { units: 0, labSeconds: 0, packs: {} }
  const triggerTechs = []
  const out = order.map((t) => {
    const unitSeconds = t.researchUnitEnergy / 60
    const packs = {}
    for (const i of t.scienceIngredients) {
      packs[i.name.replace("-science-pack", "")] = i.amount * t.researchUnitCount
      totals.packs[i.name] = (totals.packs[i.name] || 0) + i.amount * t.researchUnitCount
    }
    totals.units += t.researchUnitCount
    totals.labSeconds += t.researchUnitCount * unitSeconds
    const trig = t.researchTriggerJSON || null
    if (trig) triggerTechs.push({ name: t.name, trigger: JSON.parse(trig) })
    return { name: t.name, available: t.available, units: t.researchUnitCount, unitSeconds, packs, trigger: trig && JSON.parse(trig) }
  })
  const res = { target: input.technology, count: out.length, totals, triggerTechs, order: out }
  if (input.labs) res.estimatedMinutesAtSpeed1 = +(totals.labSeconds / input.labs / 60).toFixed(1)
  return res
}
